<script setup lang="ts">
import { computed,ref,watch } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import {api,genres,message,type Work,type Tag} from '../api'
import Icon from '../components/Icon.vue'
import WorkCard from '../components/WorkCard.vue'
import WorkRow from '../components/WorkRow.vue'
const route=useRoute(),router=useRouter(),isHome=computed(()=>route.path==='/')
const works=ref<Work[]>([]),tags=ref<Tag[]>([]),loading=ref(true),error=ref(''),total=ref(0),q=ref(String(route.query.q||''))
const genre=computed(()=>String(route.query.genre||'全部')),page=computed(()=>Number(route.query.page)||1),activity=computed(()=>tags.value.find(t=>t.isActivity))
let sequence=0
const layout=ref<'cards'|'rows'>('cards')
try{if(localStorage.getItem('haiyan.feedLayout')==='rows')layout.value='rows'}catch{}
watch(layout,value=>{try{localStorage.setItem('haiyan.feedLayout',value)}catch{}})
async function load(){const token=++sequence;loading.value=true;error.value='';try{const [w,t]=await Promise.all([api.get('/public/works',{params:{...route.query,genre:genre.value==='全部'?'':genre.value}}),api.get('/public/tags')]);if(token!==sequence)return;works.value=w.data.items;total.value=w.data.total;tags.value=t.data}catch(e){if(token===sequence)error.value=message(e)}finally{if(token===sequence)loading.value=false}}
function filter(p:Record<string,unknown>){router.push({path:'/explore',query:{...route.query,page:undefined,...p} as any})}
watch(()=>route.query,load,{immediate:true})
</script>
<template><div class="container"><section v-if="isHome" class="hero"><div class="hero-copy"><p class="eyebrow"><span></span>校园文学社的共同书页</p><h1>把日常写成诗，<br/>把心事寄给<span>远方。</span></h1><p class="hero-intro">社员原创作品、诗集与连载。<br/>记录校园生活，分享你的文字。</p><div class="hero-buttons"><RouterLink to="/write" class="button">开始写作<Icon name="ArrowUpRight"/></RouterLink><RouterLink to="/explore" class="text-button">阅读作品<Icon name="ArrowRight"/></RouterLink></div><p class="hero-footnote">诗歌 / 散文 / 小说 / 随笔 · 不限体裁</p></div><div class="hero-art" aria-hidden="true"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><span class="art-caption">LET WORDS<br/>TAKE FLIGHT.</span><div class="paper paper-back"></div><div class="paper paper-front"><span class="paper-issue">海燕 · 文学手记</span><div class="paper-stroke"></div><p>风有来处<br/>字有<span>回声</span></p><span class="paper-line"></span><span class="paper-line short"></span><span class="paper-sign">海燕传信</span><svg class="paper-bird" viewBox="0 0 48 48"><path d="M5 13 25 22 43 7 32 27 39 39 23 32 11 42 16 25Z" fill="currentColor"/></svg></div><div class="art-stamp">写<br/>在<br/>此<br/>刻</div></div></section>
<section v-if="isHome&&activity" class="activity-strip"><span class="tag-pill">正在征集</span><RouterLink :to="{path:'/explore',query:{tag:activity.id}}"><strong>{{activity.name}}</strong><span>{{activity.description}}</span></RouterLink><RouterLink to="/activities" class="strip-link">查看活动<Icon name="ArrowRight" :size="16"/></RouterLink></section>
<section class="library-section"><div class="section-heading"><div><p class="eyebrow">{{isHome?'近期发表':'作品'}}</p><h2>{{isHome?'最新作品':'作品书架'}}<span class="section-count">{{total}} 篇</span></h2></div><RouterLink v-if="isHome" to="/explore" class="text-button">浏览全部<Icon name="ArrowUpRight" :size="16"/></RouterLink><form v-else class="search-box" @submit.prevent="filter({q})"><Icon name="Search" :size="17"/><input v-model="q" placeholder="搜索作品、作者或正文" aria-label="搜索作品"/><button type="submit">搜索</button></form></div>
<div class="feed-controls"><div class="view-switch" role="group" aria-label="信息流展示方式"><button :class="{selected:layout==='rows'}" :aria-pressed="layout==='rows'" @click="layout='rows'">横条</button><button :class="{selected:layout==='cards'}" :aria-pressed="layout==='cards'" @click="layout='cards'">卡片</button></div></div><div class="filter-bar"><div class="genre-tabs"><button v-for="g in genres" :key="g" :class="{selected:genre===g}" @click="filter({genre:g==='全部'?undefined:g})">{{g}}</button></div><select aria-label="排序方式" :value="route.query.sort||'latest'" @change="filter({sort:($event.target as HTMLSelectElement).value})"><option value="latest">最新发布</option><option value="popular">最多喜欢</option></select></div><div v-if="!isHome" class="tag-filters"><button :class="{selected:!route.query.tag}" @click="filter({tag:undefined})">全部标签</button><button v-for="t in tags" :key="t.id" :class="{selected:String(t.id)===route.query.tag}" @click="filter({tag:t.id})"># {{t.name}}</button></div>
<div v-if="loading" class="empty-state">加载中…</div><div v-else-if="error" class="empty-state"><p>{{error}}</p><button class="button secondary" @click="load">重新加载</button></div><div v-else-if="!works.length" class="empty-state"><Icon name="BookOpen" :size="32"/><h3>暂无作品</h3><p>试试其他关键词或筛选条件。</p><RouterLink to="/write" class="button secondary">投稿</RouterLink></div><div v-else-if="layout==='rows'" class="works-rows"><WorkRow v-for="w in works" :key="w.id" :work="w"/></div><div v-else class="works-grid"><WorkCard v-for="(w,i) in works" :key="w.id" :work="w" :index="i"/></div><div v-if="total>12" class="pagination"><button :disabled="page===1" @click="filter({page:page-1})">上一页</button><span>{{page}} / {{Math.ceil(total/12)}}</span><button :disabled="page*12>=total" @click="filter({page:page+1})">下一页</button></div></section>
</div></template>
